WITH base AS (SELECT id, customer_id, started_at, CASE WHEN device IN ('tablet', 'desktop') THEN 'Tier 1' ELSE 'Other' END AS device_group FROM sessions WHERE country IS NOT NULL), with_prev AS (SELECT *, LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) AS prev_started_at FROM base), gaps AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM with_prev), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT customer_id, PERCENTILE_APPROX(new_group_flag, 0.5) AS new_group_flag_p50, MIN(session_id) AS min_session_id, MIN(session_id) AS min_session_id_2, COUNT(*) AS cnt FROM sessionized GROUP BY customer_id
